  for(int i=0; i<4; i++) {
    if(digitalRead(LANES[i]) == LOW) { // Vehicle detected
      digitalWrite(GREENS[i], HIGH); digitalWrite(REDS[i], LOW);
      delay(10000);
      digitalWrite(GREENS[i], LOW); digitalWrite(REDS[i], HIGH);
    }
  }
  delay(100);
}

#include <Wire.h>
#include <Adafruit_GFX.h>
#include <Adafruit_SSD1306.h>
#include <SDS011.h>

// -------- OLED CONFIG ----------
#define SCREEN_WIDTH 128
#define SCREEN_HEIGHT 64
#define OLED_RESET -1
#define OLED_ADDR 0x3C

Adafruit_SSD1306 display(SCREEN_WIDTH, SCREEN_HEIGHT, &Wire, OLED_RESET);

// -------- SDS011 CONFIG --------
#define SDS_RX 16
#define SDS_TX 17

SDS011 sds;
HardwareSerial sdsSerial(2);

// -------- VARIABLES -----------
float pm25, pm10;

void setup() {
  Serial.begin(115200);

  // OLED Init
  Wire.begin(21, 22);
  if (!display.begin(SSD1306_SWITCHCAPVCC, OLED_ADDR)) {
    Serial.println("OLED not found!");
    while (1);
  }

  display.clearDisplay();
  display.setTextSize(1);
  display.setTextColor(WHITE);
  display.setCursor(10, 20);
  display.println("Air Monitor");
  display.display();
  delay(2000);

  // SDS011 Init
  sdsSerial.begin(9600, SERIAL_8N1, SDS_RX, SDS_TX);
  sds.begin(&sdsSerial);
}

void loop() {
  if (sds.read(&pm25, &pm10) == 0) {

    Serial.printf("PM2.5: %.2f | PM10: %.2f\n", pm25, pm10);

    display.clearDisplay();
    display.setTextSize(1);

    display.setCursor(0, 0);
    display.println("Air Quality");

    display.setCursor(0, 20);
    display.print("PM2.5: ");
    display.print(pm25);
    display.println(" ug/m3");

    display.setCursor(0, 40);
    display.print("PM10: ");
    display.print(pm10);
    display.println(" ug/m3");

    display.display();
  }
  delay(1000);
}

#include <Wire.h>
#include <Adafruit_GFX.h>
#include <Adafruit_SSD1306.h>

#define TRIG 5
#define ECHO 18
#define BUZZER 26
#define SCREEN_WIDTH 128
#define SCREEN_HEIGHT 64

Adafruit_SSD1306 display(SCREEN_WIDTH, SCREEN_HEIGHT, &Wire, -1);

void setup() {
  Serial.begin(115200);
  pinMode(TRIG, OUTPUT);
  pinMode(ECHO, INPUT);
  pinMode(BUZZER, OUTPUT);
  Wire.begin(21, 22);
  display.begin(SSD1306_SWITCHCAPVCC, 0x3C);
  display.clearDisplay();
  display.setCursor(10, 20);
  display.setTextColor(WHITE);
  display.println("Smart Bin System");
  display.display();
  delay(2000);
}

void loop() {
  digitalWrite(TRIG, LOW);
  delayMicroseconds(2);
  digitalWrite(TRIG, HIGH);
  delayMicroseconds(10);
  digitalWrite(TRIG, LOW);
  long duration = pulseIn(ECHO, HIGH);
  int distance = duration * 0.034 / 2;

  display.clearDisplay();
  display.setCursor(0, 0);
  display.print("Fill Level: ");
  display.print(distance);
  display.println(" cm");

  if (distance < 10) {
    display.println("BIN FULL!");
    digitalWrite(BUZZER, HIGH);
  } else {
    digitalWrite(BUZZER, LOW);
  }
  display.display();
  delay(2000);
}

// Pro Vehicle Asset Tracker
// Hardware: ESP32 + SIM800L + Neo-6M GPS

#include <TinyGPS++.h>
#include <HardwareSerial.h>

TinyGPSPlus gps;
HardwareSerial GPS_Serial(2);

void setup() {
  Serial.begin(115200);
  GPS_Serial.begin(9600, SERIAL_8N1, 4, 5);
  Serial.println("Booting Logistics Tracker...");
}

void loop() {
  while (GPS_Serial.available() > 0) {
    if (gps.encode(GPS_Serial.read())) {
      if (gps.location.isValid()) {
        Serial.print("LAT: "); Serial.println(gps.location.lat(), 6);
        Serial.print("LNG: "); Serial.println(gps.location.lng(), 6);
        Serial.print("SPEED: "); Serial.println(gps.speed.kmph());
      }
    }
  }

  if (millis() > 5000 && gps.charsProcessed() < 10) {
    Serial.println("No GPS Hardware Detected Check Wiring!");
  }
}
